package com.battlemanson.codekanban;

import android.content.*;
import android.util.AtomicFile;
import com.google.android.gms.tasks.*;
import com.google.firebase.auth.*;
import com.google.firebase.firestore.*;
import org.json.*;
import java.io.*;
import java.lang.ref.WeakReference;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.function.Consumer;

/** Shared board transport. Authoritative ACLs are separate from editable record payloads. */
final class CloudSharing {
    interface Host {JSONObject cloudData();boolean sharedApply(JSONArray boards);void cloudStatus();}
    private static CloudSharing instance;
    static synchronized CloudSharing get(Context c){if(instance==null)instance=new CloudSharing(c.getApplicationContext());return instance;}
    private final Context context;final FirebaseAuth auth=FirebaseAuth.getInstance();private final FirebaseFirestore db=FirebaseFirestore.getInstance();
    private WeakReference<Host> host=new WeakReference<>(null);private final Map<String,Session> sessions=new TreeMap<>();private ListenerRegistration roots;private String uid="",status="",error="";private boolean needsApply,publishing;
    private static final class Session {final String id;JSONObject meta;CloudReplica replica=new CloudReplica();final Map<String,String> kinds=new HashMap<>();ListenerRegistration acl,records,children;boolean denied,writing,inModel,ready;Session(String id){this.id=id;}}
    private CloudSharing(Context c){context=c;auth.addAuthStateListener(a->{stop();Host h=host.get();if(h!=null)start();});}
    private void message(String value){status=value;Host h=host.get();if(h!=null)h.cloudStatus();}
    String status(){int count=0,pending=0;for(Session s:sessions.values())if(s.ready){count++;pending+=s.replica.pending.size();}return "Shared boards: "+count+" · "+pending+" pending changes"+(error.isEmpty()?(status.isEmpty()?"":" · "+status):" · "+error);}
    private Map<String,JSONObject> metadata(){Map<String,JSONObject> result=new HashMap<>();for(Session s:sessions.values())if(!s.denied&&s.meta!=null)result.put(s.id,s.meta);return result;}
    String role(String localId){if(!localId.startsWith("shared:"))return "owner";return BoardPermissions.role(uid,localId.substring(7),metadata());}
    boolean writable(String localId){return BoardPermissions.writable(role(localId));}
    boolean owner(String localId){return role(localId).equals("owner");}
    JSONObject meta(String id){Session s=sessions.get(id);return s==null?null:s.meta;}
    void attach(Host h){host=new WeakReference<>(h);start();}
    void detach(Host h){if(host.get()==h){host=new WeakReference<>(null);removeListeners();}}
    private void removeListeners(){if(roots!=null)roots.remove();roots=null;for(Session s:sessions.values()){if(s.acl!=null)s.acl.remove();if(s.records!=null)s.records.remove();if(s.children!=null)s.children.remove();s.acl=s.records=s.children=null;}}
    private void stop(){removeListeners();sessions.clear();uid="";needsApply=false;publishing=false;error="";status="";}
    private DocumentReference board(String id){return db.collection("sharedBoards").document(id);}
    private AtomicFile file(){return new AtomicFile(new File(context.getFilesDir(),"sharing-"+CloudRecords.id("user",uid,"")+".json"));}
    private void persist(){if(uid.isEmpty())return;try{JSONObject root=new JSONObject();for(Session s:sessions.values())if(s.ready)root.put(s.id,new JSONObject().put("meta",s.meta==null?JSONObject.NULL:s.meta).put("denied",s.denied).put("replica",s.replica.json()).put("kinds",new JSONObject(s.kinds)));AtomicFile file=file();FileOutputStream out=file.startWrite();try{out.write(root.toString().getBytes(StandardCharsets.UTF_8));file.finishWrite(out);Host current=host.get();if(current!=null)current.cloudStatus();}catch(Exception e){file.failWrite(out);throw e;}}catch(Exception e){error="Could not save collaboration queue: "+e.getMessage();message(error);}}
    private void load()throws Exception{try(InputStream in=file().openRead();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);JSONObject root=new JSONObject(out.toString("UTF-8"));Iterator<String> keys=root.keys();while(keys.hasNext()){String id=keys.next();JSONObject value=root.getJSONObject(id);Session s=new Session(id);s.ready=true;s.meta=value.optJSONObject("meta");s.denied=value.optBoolean("denied");s.replica=CloudReplica.read(value.getJSONObject("replica"));JSONObject kinds=value.optJSONObject("kinds");if(kinds!=null){Iterator<String> k=kinds.keys();while(k.hasNext()){String key=k.next();s.kinds.put(key,kinds.getString(key));}}sessions.put(id,s);}}catch(FileNotFoundException firstUse){}}
    private void start(){FirebaseUser user=auth.getCurrentUser();if(user==null||roots!=null)return;try{if(!uid.equals(user.getUid())){removeListeners();sessions.clear();uid=user.getUid();load();}final String account=uid;
            roots=db.collection("users").document(account).collection("sharedRoots").addSnapshotListener((snapshot,failure)->{if(!account.equals(uid))return;if(failure!=null){message("Collaboration: "+failure.getMessage()+". Publish the updated Firestore rules.");return;}if(snapshot!=null){status="Collaboration connected";for(DocumentSnapshot d:snapshot.getDocuments())watch(d.getId());needsApply=true;apply();message(status);}});
            for(String id:new ArrayList<>(sessions.keySet()))if(sessions.get(id).ready)watch(id);Host h=host.get();if(h!=null){JSONArray local=h.cloudData().getJSONArray("boards");for(int i=0;i<local.length();i++){Session s=sessions.get(BoardPermissions.sharedId(local.getJSONObject(i)));if(s!=null)s.inModel=true;}localSaved(h.cloudData());}
        }catch(Exception e){error="Collaboration cache unavailable: "+e.getMessage();message(error);}}
    void refresh(){removeListeners();start();needsApply=true;apply();}
    private JSONObject policy(DocumentSnapshot d)throws JSONException{return new JSONObject().put("ownerId",d.getString("ownerId")).put("parentId",d.getString("parentId")).put("ancestors",new JSONArray((List<?>)d.get("ancestors"))).put("grants",new JSONObject((Map<?,?>)d.get("grants"))).put("emails",new JSONObject((Map<?,?>)d.get("emails"))).put("deleted",Boolean.TRUE.equals(d.getBoolean("deleted")));}
    private void watch(String id){Session s=sessions.computeIfAbsent(id,Session::new);s.ready=true;if(s.acl!=null)return;final String account=uid;s.denied=false;
        s.acl=board(id).addSnapshotListener((snapshot,failure)->{if(!account.equals(uid))return;
            if(failure!=null||snapshot==null||!snapshot.exists()){s.denied=true;if(s.acl!=null)s.acl.remove();if(s.records!=null)s.records.remove();if(s.children!=null)s.children.remove();s.acl=s.records=s.children=null;needsApply=true;persist();apply();return;}
            try{s.meta=policy(snapshot);s.denied=false;JSONObject grants=s.meta.getJSONObject("grants");if(uid.equals(s.meta.getString("ownerId"))||!grants.has(uid)){JSONArray parents=s.meta.getJSONArray("ancestors");for(int p=parents.length()-1;p>=0;p--)watch(parents.getString(p));}
                for(Session known:new ArrayList<>(sessions.values()))watchContent(known,account);
                persist();needsApply=true;apply();flush(s);
            }catch(Exception e){message("Could not read board permissions: "+e.getMessage());}
        });
    }
    private void watchContent(Session s,String account){String id=s.id;if(!s.ready||s.denied||!BoardPermissions.readable(role(BoardPermissions.localId(id)))){if(s.records!=null)s.records.remove();if(s.children!=null)s.children.remove();s.records=s.children=null;return;}

                    if(s.records==null)s.records=board(id).collection("records").addSnapshotListener(MetadataChanges.INCLUDE,(data,problem)->{if(!account.equals(uid))return;if(problem!=null){s.denied=true;if(s.records!=null)s.records.remove();s.records=null;needsApply=true;persist();apply();return;}if(data==null)return;try{Map<String,String> incoming=new TreeMap<>();for(DocumentSnapshot d:data.getDocuments()){String json=d.getString("json"),kind=d.getString("kind");if(!Long.valueOf(1).equals(d.getLong("schema"))||json==null||kind==null)throw new JSONException("Unsupported shared record.");JSONObject parsed=new JSONObject(json);if(!parsed.optBoolean("deleted")&&(!id.equals(parsed.optString("boardId"))||!kind.equals(parsed.optString("kind"))))throw new JSONException("Shared record identity mismatch.");incoming.put(d.getId(),json);s.kinds.put(d.getId(),kind);}s.replica.remote(incoming,!data.getMetadata().isFromCache());persist();needsApply=true;apply();}catch(Exception e){message("Could not receive shared board: "+e.getMessage());}});
                    if(s.children==null)s.children=board(id).collection("children").addSnapshotListener((children,problem)->{if(!account.equals(uid)||children==null)return;for(DocumentSnapshot child:children.getDocuments())watch(child.getId());});
    }
    boolean checkWrites(JSONObject before,JSONObject after)throws JSONException{return BoardPermissions.checkWrites(before,after,uid,metadata());}
    void localSaved(JSONObject data){if(uid.isEmpty()||publishing)return;try{Map<String,JSONObject> local=new HashMap<>();JSONArray boards=data.getJSONArray("boards");for(int i=0;i<boards.length();i++){JSONObject b=boards.getJSONObject(i);if(b.has("_shared"))local.put(BoardPermissions.sharedId(b),b);}
            for(Session s:sessions.values())if(s.ready&&writable(BoardPermissions.localId(s.id))){JSONObject b=local.get(s.id);if(b==null&&!s.inModel)continue;s.inModel=b!=null;Map<String,String> encoded=b==null?Collections.emptyMap():BoardPermissions.records(b);for(Map.Entry<String,String> entry:encoded.entrySet())s.kinds.put(entry.getKey(),new JSONObject(entry.getValue()).getString("kind"));s.replica.local(encoded);}
            persist();for(Session s:sessions.values())flush(s);
        }catch(Exception e){error="Shared upload queue failed: "+e.getMessage();message(error);}}
    private void flush(Session s){if(s.writing||s.replica.pending.isEmpty()||!writable(BoardPermissions.localId(s.id)))return;s.writing=true;final String account=uid;Map<String,CloudReplica.Write> sent=new LinkedHashMap<>();WriteBatch batch=db.batch();for(Map.Entry<String,CloudReplica.Write> e:s.replica.pending.entrySet()){if(sent.size()==300)break;sent.put(e.getKey(),e.getValue());Map<String,Object> doc=new HashMap<>();doc.put("schema",1);doc.put("json",e.getValue().json);doc.put("kind",s.kinds.get(e.getKey()));doc.put("changeId",e.getValue().token);doc.put("updatedAt",FieldValue.serverTimestamp());batch.set(board(s.id).collection("records").document(e.getKey()),doc);}
        batch.commit().addOnCompleteListener(task->{if(!account.equals(uid))return;s.writing=false;if(task.isSuccessful()){for(Map.Entry<String,CloudReplica.Write> e:sent.entrySet())s.replica.acknowledged(e.getKey(),e.getValue().token);error="";persist();flush(s);}else{error="Shared write rejected or offline; changes remain queued: "+(task.getException()==null?"Unknown error":task.getException().getMessage());message(error);}});
    }
    void apply(){if(!needsApply||publishing)return;Host h=host.get();if(h==null)return;try{Set<String> visible=new HashSet<>();for(Session s:sessions.values())if(s.ready&&BoardPermissions.readable(role(BoardPermissions.localId(s.id))))visible.add(s.id);JSONArray boards=new JSONArray();for(String id:visible){Session s=sessions.get(id);JSONObject b=BoardPermissions.localBoard(id,s.meta,s.replica.records,visible);if(b!=null){String policy=CloudRecords.canonical(s.meta);JSONArray chain=s.meta.optJSONArray("ancestors");if(chain!=null)for(int a=0;a<chain.length();a++){JSONObject ancestor=meta(chain.optString(a));if(ancestor!=null)policy+=CloudRecords.canonical(ancestor);}b.getJSONObject("_shared").put("role",role(BoardPermissions.localId(id))).put("policyVersion",CloudRecords.id("policy",policy,""));boards.put(b);}}if(h.sharedApply(boards)){for(String id:visible){Session s=sessions.get(id);JSONObject board=null;JSONArray local=h.cloudData().getJSONArray("boards");for(int i=0;i<local.length();i++)if(id.equals(BoardPermissions.sharedId(local.getJSONObject(i))))board=local.getJSONObject(i);s.inModel=board!=null;if(board!=null){s.replica.lastLocal.clear();s.replica.lastLocal.putAll(BoardPermissions.records(board));}}needsApply=false;persist();}}catch(Exception e){message("Could not apply shared boards: "+e.getMessage());}}
    Map<String,String> members(String id){Map<String,String> result=new LinkedHashMap<>();JSONObject meta=meta(id);if(meta==null)return result;List<String> chain=new ArrayList<>();JSONArray parents=meta.optJSONArray("ancestors");if(parents!=null)for(int i=0;i<parents.length();i++)chain.add(parents.optString(i));chain.add(id);for(String board:chain){JSONObject b=meta(board);if(b==null)continue;JSONObject emails=b.optJSONObject("emails");if(emails!=null){Iterator<String> ids=emails.keys();while(ids.hasNext()){String user=ids.next();result.put(user,emails.optString(user,user));}}}return result;}
    String memberRole(String id,String user){return BoardPermissions.role(user,id,metadata());}
    String explicitRole(String id,String user){JSONObject meta=meta(id),grants=meta==null?null:meta.optJSONObject("grants");return grants==null?"inherit":grants.optString(user,"inherit");}
    void sentInvites(String id,Consumer<List<DocumentSnapshot>> done,Consumer<String> failure){db.collection("boardInvites").whereEqualTo("ownerId",uid).get(Source.SERVER).addOnCompleteListener(t->{if(!t.isSuccessful()){failure.accept(t.getException().getMessage());return;}List<DocumentSnapshot> pending=new ArrayList<>();for(DocumentSnapshot d:t.getResult().getDocuments())if(id.equals(d.getString("boardId"))&&"pending".equals(d.getString("state")))pending.add(d);done.accept(pending);});}
    void revokeInvite(DocumentSnapshot invite,Consumer<String> done){invite.getReference().update("state","revoked").addOnCompleteListener(t->done.accept(t.isSuccessful()?null:t.getException().getMessage()));}
    void invite(String id,String name,String email,String role,Consumer<String> done){if(!owner(BoardPermissions.localId(id))){done.accept("Only the board owner can invite people.");return;}Map<String,Object> invitation=new HashMap<>();invitation.put("boardId",id);invitation.put("boardName",name);invitation.put("ownerId",uid);invitation.put("email",email.trim().toLowerCase(Locale.ROOT));invitation.put("role",role);invitation.put("state","pending");invitation.put("acceptedBy","");invitation.put("createdAt",FieldValue.serverTimestamp());db.collection("boardInvites").add(invitation).addOnCompleteListener(t->done.accept(t.isSuccessful()?null:t.getException().getMessage()));}
    void invitations(Consumer<List<DocumentSnapshot>> success,Consumer<String> failure){FirebaseUser user=auth.getCurrentUser();if(user==null||!user.isEmailVerified()){failure.accept("Verify your email, then refresh your account before opening invitations.");return;}db.collection("boardInvites").whereEqualTo("email",user.getEmail().toLowerCase(Locale.ROOT)).get(Source.SERVER).addOnCompleteListener(t->{if(t.isSuccessful()){List<DocumentSnapshot> pending=new ArrayList<>();for(DocumentSnapshot d:t.getResult().getDocuments())if("pending".equals(d.getString("state")))pending.add(d);success.accept(pending);}else failure.accept(t.getException().getMessage());});}
    void respond(DocumentSnapshot invitation,boolean accept,Consumer<String> done){String account=uid;DocumentReference reference=invitation.getReference(),target=board(invitation.getString("boardId"));WriteBatch batch=db.batch();if(accept){Map<String,Object> change=new HashMap<>();change.put("grants."+account,invitation.getString("role"));change.put("emails."+account,auth.getCurrentUser().getEmail().toLowerCase(Locale.ROOT));change.put("acceptedInvite",invitation.getId());change.put("updatedAt",FieldValue.serverTimestamp());batch.update(target,change);batch.update(reference,"state","accepted","acceptedBy",account);batch.set(db.collection("users").document(account).collection("sharedRoots").document(invitation.getString("boardId")),new HashMap<String,Object>(){{put("boardId",invitation.getString("boardId"));put("updatedAt",FieldValue.serverTimestamp());}});}else batch.update(reference,"state","declined");batch.commit().addOnCompleteListener(t->{if(t.isSuccessful())refresh();done.accept(t.isSuccessful()?null:t.getException().getMessage());});}
    void permission(String id,String user,String role,Consumer<String> done){if(!owner(BoardPermissions.localId(id))||user.equals(uid)){done.accept("Only the board owner can change collaborator access.");return;}Map<String,Object> changes=new HashMap<>();changes.put("grants."+user,role.equals("inherit")?FieldValue.delete():role);changes.put("updatedAt",FieldValue.serverTimestamp());WriteBatch batch=db.batch();batch.update(board(id),changes);Map<String,Object> pointer=new HashMap<>();pointer.put("boardId",id);pointer.put("updatedAt",FieldValue.serverTimestamp());batch.set(db.collection("users").document(user).collection("sharedRoots").document(id),pointer);batch.commit().addOnCompleteListener(t->done.accept(t.isSuccessful()?null:t.getException().getMessage()));}
    void publish(JSONObject data,String selected,Consumer<String> done){if(auth.getCurrentUser()==null){done.accept("Sign in to cloud sync first.");return;}if(publishing){done.accept("A board is already being shared.");return;}try{List<JSONObject> pending=new ArrayList<>();JSONArray boards=data.getJSONArray("boards");Set<String> chosen=new HashSet<>();chosen.add(selected);boolean changed=true;while(changed){changed=false;for(int i=0;i<boards.length();i++){JSONObject b=boards.getJSONObject(i);if(chosen.contains(b.optString("parent"))&&chosen.add(b.optString("id")))changed=true;}}
            while(pending.size()<chosen.size()){boolean added=false;for(int i=0;i<boards.length();i++){JSONObject b=boards.getJSONObject(i);if(!chosen.contains(b.optString("id"))||b.has("_shared"))continue;boolean exists=false;for(JSONObject old:pending)exists|=old.optString("id").equals(b.optString("id"));if(exists)continue;String parent=b.optString("parent");if(!chosen.contains(parent)||pending.stream().anyMatch(old->old.optString("id").equals(parent))){pending.add(BoardTemplate.copy(b));added=true;}}if(!added)break;}
            if(pending.isEmpty())throw new JSONException("No private board selected.");Map<String,Integer> depths=new HashMap<>();for(JSONObject b:pending){String parent=b.optString("parent");int depth=depths.containsKey(parent)?depths.get(parent)+1:0;if(parent.startsWith("shared:")){JSONObject policy=meta(parent.substring(7));if(policy==null)throw new JSONException("Parent permissions are not loaded.");depth=policy.getJSONArray("ancestors").length()+1;}if(depth>=BoardPermissions.MAX_DEPTH)throw new JSONException("Shared board nesting supports up to 8 levels. This tree was not changed.");depths.put(b.optString("id"),depth);}
            for(Map.Entry<String,?> state:context.getSharedPreferences(ReminderScheduler.PREFS,Context.MODE_PRIVATE).getAll().entrySet())if(state.getKey().startsWith("active/")&&Boolean.TRUE.equals(state.getValue()))throw new JSONException("Dismiss or snooze active alarms before enabling collaboration.");publishing=true;publishNext(pending,0,uid,done);
        }catch(Exception e){done.accept(e.getMessage());}}
    private void publishNext(List<JSONObject> boards,int at,String account,Consumer<String> done){if(!account.equals(uid)){done.accept("Account changed; sharing cancelled.");return;}if(at==boards.size()){publishIndexes(boards,0,account,done);return;}JSONObject local=boards.get(at);String id=local.optString("id"),parent=local.optString("parent");String sharedParent=parent.startsWith("shared:")?parent.substring(7):sessions.containsKey(parent)?parent:"";Session parentSession=sessions.get(sharedParent);if(!sharedParent.isEmpty()&&(parentSession==null||parentSession.meta==null)){publishing=false;done.accept("Parent permissions are not loaded.");return;}
        try{JSONArray ancestors=parentSession==null?new JSONArray():new JSONArray(parentSession.meta.getJSONArray("ancestors").toString());if(parentSession!=null)ancestors.put(sharedParent);if(ancestors.length()>=BoardPermissions.MAX_DEPTH)throw new JSONException("Shared board nesting supports up to 8 levels.");JSONObject meta=new JSONObject().put("ownerId",uid).put("parentId",sharedParent).put("ancestors",ancestors).put("grants",new JSONObject()).put("emails",new JSONObject()).put("deleted",false);
            Map<String,Object> policy=new HashMap<>();policy.put("ownerId",uid);policy.put("parentId",sharedParent);List<String> chain=new ArrayList<>();for(int a=0;a<ancestors.length();a++)chain.add(ancestors.getString(a));policy.put("ancestors",chain);policy.put("grants",new HashMap<>());policy.put("emails",new HashMap<>());policy.put("deleted",false);policy.put("updatedAt",FieldValue.serverTimestamp());
            board(id).get(Source.SERVER).addOnCompleteListener(check->{if(!account.equals(uid)){done.accept("Account changed; sharing cancelled.");return;}if(!check.isSuccessful()){publishing=false;done.accept(check.getException().getMessage());return;}Task<Void> ensure;if(check.getResult().exists()){if(!uid.equals(check.getResult().getString("ownerId"))){publishing=false;done.accept("This board ID belongs to another owner.");return;}try{meta.keys();JSONObject existing=policy(check.getResult());Session session=sessions.computeIfAbsent(id,Session::new);session.meta=existing;}catch(Exception e){publishing=false;done.accept(e.getMessage());return;}ensure=Tasks.forResult(null);}else ensure=board(id).set(policy);
                ensure.addOnCompleteListener(created->{if(!account.equals(uid)){done.accept("Account changed; sharing cancelled.");return;}if(!created.isSuccessful()){publishing=false;done.accept(created.getException().getMessage());return;}try{Session session=sessions.computeIfAbsent(id,Session::new);if(session.meta==null)session.meta=meta;JSONObject copy=BoardTemplate.copy(local);copy.put("_shared",new JSONObject().put("id",id).put("ownerId",uid).put("parentId",sharedParent));Map<String,String> records=BoardPermissions.records(copy);List<Map.Entry<String,String>> entries=new ArrayList<>(records.entrySet());publishRecords(session,entries,0,account,error->{if(error!=null){publishing=false;done.accept(error);return;}session.replica.records.putAll(records);session.replica.lastLocal.putAll(records);publishNext(boards,at+1,account,done);});}catch(Exception e){publishing=false;done.accept(e.getMessage());}});
            });
        }catch(Exception e){publishing=false;done.accept(e.getMessage());}
    }
    private void publishIndexes(List<JSONObject> boards,int at,String account,Consumer<String> done){if(!account.equals(uid)){done.accept("Account changed; sharing cancelled.");return;}
        if(at==boards.size()){for(JSONObject b:boards){Session s=sessions.get(b.optString("id"));if(s!=null)s.ready=true;}publishing=false;persist();needsApply=true;refresh();apply();done.accept(null);return;}
        String id=boards.get(at).optString("id");Session s=sessions.get(id);Map<String,Object> pointer=new HashMap<>();pointer.put("boardId",id);pointer.put("updatedAt",FieldValue.serverTimestamp());WriteBatch batch=db.batch();batch.set(db.collection("users").document(uid).collection("sharedRoots").document(id),pointer);String parent=s.meta.optString("parentId");if(!parent.isEmpty())batch.set(board(parent).collection("children").document(id),pointer);batch.commit().addOnCompleteListener(t->{if(t.isSuccessful())publishIndexes(boards,at+1,account,done);else{publishing=false;done.accept(t.getException().getMessage());}});
    }
    private void publishRecords(Session s,List<Map.Entry<String,String>> entries,int start,String account,Consumer<String> done){if(!account.equals(uid)){done.accept("Account changed; sharing cancelled.");return;}if(start>=entries.size()){done.accept(null);return;}WriteBatch batch=db.batch();int end=Math.min(start+300,entries.size());try{for(int i=start;i<end;i++){Map.Entry<String,String> entry=entries.get(i);String kind=new JSONObject(entry.getValue()).getString("kind");s.kinds.put(entry.getKey(),kind);Map<String,Object> doc=new HashMap<>();doc.put("schema",1);doc.put("json",entry.getValue());doc.put("kind",kind);doc.put("changeId",UUID.randomUUID().toString());doc.put("updatedAt",FieldValue.serverTimestamp());batch.set(board(s.id).collection("records").document(entry.getKey()),doc);}batch.commit().addOnCompleteListener(task->{if(task.isSuccessful())publishRecords(s,entries,end,account,done);else done.accept(task.getException().getMessage());});}catch(Exception e){done.accept(e.getMessage());}}
}
